# Hypothesis: lambdas and functions with defaulted or positional-only parameters are
# assignable to a Callable with fewer required parameters, while a lambda that needs
# two arguments is rejected where a one-argument Callable is expected.
from typing import Callable, reveal_type, assert_type


def run_pair(f: Callable[[int, int], int]) -> int:
    return f(2, 3)


def run_one(f: Callable[[int], int]) -> int:
    return f(2)


def scale(x: int, factor: int = 10) -> int:
    return x * factor


def first(x: int, /, *, default: int = -1) -> int:
    return x if x >= 0 else default


doubler: Callable[[int], int] = lambda n: n * 2
pick: Callable[[int], int] = lambda n, k=3: n + k
reveal_type(doubler)
reveal_type(pick)
assert_type(run_one(doubler), int)
assert run_one(doubler) == 4
assert run_one(scale) == 20
assert run_one(first) == 2
assert run_pair(scale) == 6
assert run_pair(lambda a, b: a + b) == 5
assert pick(1) == 4
assert first(-5, default=7) == 7


def bad_call() -> int:
    try:
        return run_one(lambda a, b: a + b)  # expect-error
    except TypeError:
        return -1


assert bad_call() == -1
